{"check_build": {"code": "script({title:'Imperial Star Destroyer: Pursuit of the Tantive IV', description:'A wedge-hulled Imperial I-class Star Destroyer on a display stand, terraced hull, trench, ziggurat superstructure, bridge tower with shield domes, glowing engines; the Tantive IV flees ahead.'});
const LBG='light bluish grey', DBG='dark bluish grey', TLB='trans light blue';
const Z0=-45, L=90;
const H=r=>Math.ceil((r+1)*0.3);
function excl(z){ const e=[]; if(z>=14 && z<20) e.push([-11,10]); if(z>=20) e.push([-15,14]); return e; }
function segs(a,b,ex){ let out=[[a,b]]; for(const [c,d] of ex){ const n=[]; for(const [p,q] of out){ if(d<p||c>q){n.push([p,q]);continue;} if(p<c) n.push([p,c-1]); if(q>d) n.push([d+1,q]); } out=n;} return out; }
const fl=(x0,x1,y,z,colour)=> x1>=x0 ? floor({at:[x0,y,z], size:[x1-x0+1,1], colour}) : null;
const hull=[];
for(let r=0;r<L;r++){ const z=Z0+r, h=H(r);
  hull.push(fl(-h,h-1,35,z,LBG));
  hull.push(h>1? fl(-(h-1),h-2,36,z,DBG) : fl(-h,h-1,36,z,DBG));
  hull.push(fl(-h,h-1,37,z,LBG));
  for(let k=1;k<=7;k++){ const s=h-2*k; if(s>0) hull.push(fl(-s,s-1,35-k,z,LBG)); }
  const kmc=Math.min(10,Math.floor((h-1)/2));
  const trench = z<=13 && kmc>=3;
  const ex=excl(z);
  for(let k=1;k<=10;k++){ const s=h-2*k; if(s<=0) break; const y=37+k;
    const ex2=ex.slice();
    if(trench && k>=kmc-1) ex2.push([-1,0]);
    if(trench && k===kmc-2){ ex2.push([-1,0]); hull.push(fl(-1,0,y,z,DBG)); }
    for(const [p,q] of segs(-s,s-1,ex2)) hull.push(fl(p,q,y,z,LBG));
  }
}
hull.push(smooth({region:{at:[-28,-46], size:[56,91]}}));
section('Hull', hull);

section('Display stand', [
  floor({at:[-9,0,3], size:[18,18], colour:'black'}),
  floor({at:[-8,1,4], size:[16,16], layers:3, colour:DBG, top:'tile'}),
  place({part:'87079', at:[-2,4,5], colour:'black'}),
  column({at:[-2,4,10], height:24, diameter:4, colour:DBG})
]);

section('Superstructure', [
  box({at:[-11,38,14], size:[22,9,6], colour:LBG, texture:'grille', top:'tile'}),
  ...range(11).map(i=>place({part:'3039', at:[-11+2*i,47,18], colour:LBG})),
  box({at:[-15,38,20], size:[30,12,29], colour:LBG, texture:'grille', top:'tile'}),
  box({at:[-15,50,30], size:[4,3,14], colour:DBG, top:'tile'}),
  box({at:[11,50,30], size:[4,3,14], colour:DBG, top:'tile'}),
  box({at:[-11,50,24], size:[22,6,25], colour:LBG, top:'tile'}),
  ...range(8).map(i=>place({part:'3039', at:[-8+2*i,56,28], colour:LBG})),
  box({at:[-8,56,30], size:[16,6,19], colour:LBG, texture:'grille', top:'tile'}),
  place({part:'44359', at:[-15,50,21], colour:DBG}),
  place({part:'44359', at:[12,50,21], colour:DBG}),
  place({part:'2412b', at:[-9,50,21], colour:DBG}),
