  place({part:'3957a', at:[9,56,42], colour:DBG}),
  place({part:'2412b', at:[-11,56,38], turn:90, colour:DBG}),
  place({part:'2412b', at:[10,56,37], turn:90, colour:DBG})
]);

section('Bridge tower', [
  box({at:[-5,62,32], size:[10,3,14], colour:DBG, top:'tile'}),
  box({at:[-3,65,36], size:[6,9,6], colour:LBG, texture:'grille'}),
  place({part:'3660b', at:[-5,71,36], turn:90, colour:LBG}),
  place({part:'3660b', at:[-5,71,39], turn:90, colour:LBG}),
  place({part:'3660b', at:[3,71,36], turn:270, colour:LBG}),
  place({part:'3660b', at:[3,71,39], turn:270, colour:LBG}),
  floor({at:[-9,74,35], size:[18,8], layers:2, colour:LBG}),
  floor({at:[-7,76,35], size:[14,1], layers:2, colour:'black'}),
  floor({at:[-9,76,35], size:[2,1], layers:2, colour:LBG}),
  floor({at:[7,76,35], size:[2,1], layers:2, colour:LBG}),
  floor({at:[-9,76,36], size:[18,7], layers:2, colour:LBG}),
  floor({at:[-9,78,35], size:[18,8], layers:2, colour:LBG, top:'tile'}),
  place({part:'3941', at:[-7,80,37], colour:DBG}),
  place({part:'3941', at:[5,80,37], colour:DBG}),
  place({part:'3960', at:[-8,83,36], colour:LBG}),
