  place({part:'3957a', at:[6,62,46], colour:LBG}),
  place({part:'4740', at:[5,62,40], colour:DBG}),
  place({part:'2412b', at:[-8,62,34], turn:90, colour:DBG}),
  place({part:'2412b', at:[-2,65,33], colour:DBG}),
  place({part:'3070b', at:[2,65,34], colour:DBG})
]);

const engines=[{cx:-12,cy:39.5,R:5},{cx:0,cy:39.5,R:5},{cx:12,cy:39.5,R:5},{cx:-6,cy:55,R:2},{cx:6,cy:55,R:2},{cx:-20,cy:33,R:2},{cx:20,cy:33,R:2}];
const eng=[box({at:[-23,26,45], size:[46,27,4], colour:LBG, top:'tile'}), box({at:[-10,53,45], size:[20,8,4], colour:LBG, top:'tile'})];
for(let y=26;y<62;y++){ let runT=null, runX=0; const cellT=x=>{ for(const e of engines){ const dx=x+0.5-e.cx, dy=(y+0.5-e.cy)*0.4, d=Math.sqrt(dx*dx+dy*dy); if(d<=e.R) return d>e.R-(e.R>=4?1:0.75)?'ring':'glow'; } return null; };
  const flush=(x)=>{ if(runT){ const w=x-runX; eng.push(runT==='ring'? floor({at:[runX,y,49], size:[w,2], colour:DBG}) : floor({at:[runX,y,49], size:[w,1], colour:TLB})); } };
  for(let x=-23;x<=23;x++){ const t= x<=22? cellT(x):null; if(t!==runT){ flush(x); runT=t; runX=x; } }
}
section('Engines', eng);

const occ=new Set(); const key=(x,z)=>x+','+z;
function kAt(x,z){ const r=z-Z0; if(r<0||r>=L) return -1; const h=H(r); const xr=x>=0?x+1:-x; if(xr>h) return -1; return Math.min(10,Math.floor((h-xr)/2)); }
function blocked(x,z){ if(z>=13 && x>=-16 && x<=15) return true; if(z<=14 && x>=-2 && x<=1) return true; if(z>=44) return true; return false; }
const gr=[];
const zs=[-16,-7,1,8,16,24,31,38], ks=[3,4,3,5,4,6,5,4];
zs.forEach((z0,i)=>{ const k=ks[i]; for(const side of [1,-1]){ for(const dz of [0,-1,1,-2,2]){ const z=z0+dz; const h=H(z-Z0); const xr0=h-2*k-1; if(xr0<2) continue; const x0= side>0? xr0-1 : -(xr0+1);
  const ok=[0,1].every(a=>[0,1].every(b=>kAt(x0+a,z+b)===k && !blocked(x0+a,z+b) && !occ.has(key(x0+a,z+b))));
  if(!ok) continue;
  gr.push(place({part:'4032b', at:[x0,38+k,z], colour:DBG}));
  gr.push(place({part:'4599b', at:[x0+(side>0?0:1),39+k,z+1], colour:DBG}));
  for(let a=-1;a<=2;a++) for(let b=-2;b<=2;b++) occ.add(key(x0+a,z+b));
  break; } } });
const gp=[['3024',DBG,1],['6141',DBG,1],['2412b',DBG,2],['3070b',DBG,1],['6141',LBG,1],['3023b',DBG,2],['2412b',LBG,2],['3069b',DBG,2]];
for(let z=-28;z<=43;z++) for(let x=-27;x<=26;x++){ if(blocked(x,z)||occ.has(key(x,z))) continue; const k=kAt(x,z); if(k<0) continue; const d=0.025+0.06*(z+28)/71; if(rng()>=d) continue; const p=gp[Math.floor(rng()*gp.length)];
  if(p[2]===2){ if(blocked(x+1,z)||occ.has(key(x+1,z))||kAt(x+1,z)!==k) continue; occ.add(key(x+1,z)); }
  occ.add(key(x,z)); gr.push(place({part:p[0], at:[x,38+k,z], colour:p[1]})); }
section('Turbolasers and greebles', gr);

section('Tantive IV', [
