    place({part:'85984', at:[-1,2,0], colour:'white'}),
    place({part:'85984', at:[1,2,0], colour:'white'}),
    place({part:'3069b', at:[-1,2,1], colour:'red'}),
    place({part:'3069b', at:[1,2,1], colour:'red'})
  ]})
]);
", "seed": 1}}

